upstream app {
    # The name resolves to every replica of the app service.
    server app:8000;
}

server {
    listen 80;

    # 1,000 payments with 500-character non-ASCII descriptions exceed nginx's 1 MB default.
    client_max_body_size 8m;

    location / {
        proxy_pass http://app;
        proxy_connect_timeout 2s;
        # Keeps the client's host and port in redirects the app builds.
        proxy_set_header Host $http_host;
        proxy_set_header X-Request-Id $request_id;
        add_header X-Upstream $upstream_addr always;
    }
}
